INSERT INTO thong_bao (ngay, tieu_de, noi_dung, loai, ghim) VALUES ('2026-09-05', 'Lễ khai giảng năm học 2026 – 2027', 'Học sinh có mặt tại sân trung tâm lúc 6h45, đồng phục chỉnh tề. Lớp trưởng điểm danh và báo cáo sĩ số cho giáo viên chủ nhiệm trước 7h00.', 'Nhà trường', 1);
INSERT INTO thong_bao (ngay, tieu_de, noi_dung, loai, ghim) VALUES ('2026-09-03', 'Ổn định tổ chức lớp 10A7', 'Bầu ban cán sự lớp, chia tổ, phân công trực nhật. Học sinh hoàn thiện hồ sơ đầu năm và nộp lại cho giáo viên chủ nhiệm.', 'Chủ nhiệm', 0);
INSERT INTO ke_hoach (ngay, tieu_de, mo_ta, muc_do) VALUES ('2026-09-05', 'Khai giảng năm học mới', 'Toàn thể học sinh lớp 10A7 tham dự lễ khai giảng tại sân trung tâm.', 'ok');
INSERT INTO ke_hoach (ngay, tieu_de, mo_ta, muc_do) VALUES ('2026-10-20', 'Kiểm tra giữa học kì I', 'Lịch kiểm tra chi tiết từng môn sẽ được cập nhật trong mục Thông báo.', 'warn');
INSERT INTO ke_hoach (ngay, tieu_de, mo_ta, muc_do) VALUES ('2026-11-20', 'Kỉ niệm Ngày Nhà giáo Việt Nam', 'Lớp chuẩn bị tiết mục văn nghệ và báo tường.', '');
INSERT INTO ke_hoach (ngay, tieu_de, mo_ta, muc_do) VALUES ('2026-12-25', 'Kiểm tra cuối học kì I', 'Học sinh ôn tập theo đề cương do giáo viên bộ môn cung cấp.', 'danger');
